<script setup lang="ts">
import {computed} from 'vue'
import UiIcon from '../UiIcon.vue'
import StatusBadge from '../StatusBadge.vue'
import type {MigrationReport,FileRef} from '../../lib/migration.ts'
const props=defineProps<{tab:string;report:MigrationReport;code:string;loading:boolean;error:string;canWrite:boolean;manual:{passed:boolean;lines:number|null;seconds:number|null;notes:string}}>()
const emit=defineEmits<{copy:[];download:[FileRef];feedback:[]}>()
const decisions=computed(()=>props.report.state.decisions??[])
const ssm=computed(()=>props.report.files.find(f=>f.kind==='ssm'||f.relative_path.endsWith('/ssm.json')))
</script>
<template>
  <section v-if="tab==='code'"><header class="cm-between"><div><h3>当前接受的 San 代码</h3><p class="cm-help">不是被拒绝的修复候选，也不代表质量已全部通过。</p></div><button :disabled="!code" @click="emit('copy')"><UiIcon name="copy" :size="16"/>复制代码</button></header><p v-if="error" class="cm-alert danger">{{error}}</p><p v-if="loading" class="cm-help">正在读取登记产物…</p><pre v-if="code" class="cm-code-block"><code>{{code}}</code></pre><div v-else-if="!loading" class="cm-empty">尚未生成可下载的接受产物。</div><p class="cm-help cm-hash">SHA-256 {{report.final_artifact?.sha256??'未记录'}}</p></section>
  <section v-else-if="tab==='repairs'"><header class="cm-between"><div><h3>候选修复与回退记录</h3><p class="cm-help">接受修复进步不等于迁移通过；生成与规则／模型候选保持原账本。</p></div><span class="cm-count">{{decisions.length}} 轮</span></header><ol v-if="decisions.length" class="cm-repair-timeline"><li v-for="decision in decisions" :key="decision.round"><span class="cm-round-number">{{decision.round}}</span><article><header class="cm-between"><h4>第 {{decision.round}} 轮修复候选</h4><StatusBadge :status="decision.accepted?'pass':'fail'" :label="decision.accepted?'接受进步':'拒绝并回退'"/></header><p><code>{{decision.reason}}</code></p><dl class="cm-facts"><dt>父版本</dt><dd><code>{{decision.previous.slice(0,16)}}</code></dd><dt>候选版本</dt><dd><code>{{decision.candidate.slice(0,16)}}</code></dd></dl><p v-if="decision.added_errors?.length" class="cm-help">新增错误：{{decision.added_errors.join('、')}}</p><details><summary>查看原始决策证据</summary><pre>{{JSON.stringify(decision,null,2)}}</pre></details></article></li></ol><div v-else class="cm-empty"><UiIcon name="tool" :size="32"/><strong>尚无修复候选决策</strong><p>未运行修复不代表自动修复成功。</p></div></section>
  <section v-else><header class="cm-between"><h3>证据与全部产物</h3><button v-if="ssm" @click="emit('download',ssm)"><UiIcon name="layers" :size="17"/>下载 SSM</button></header><div class="cm-artifact-list"><button v-for="file in report.files" :key="file.relative_path" @click="emit('download',file)"><UiIcon name="file" :size="17"/><span>{{file.relative_path.split('/').slice(2).join('/')}}<small>{{file.sha256.slice(0,20)}}</small></span><UiIcon name="download" :size="16"/></button></div>
    <details v-if="report.final_artifact" class="cm-details"><summary>追加人工验收 <span>{{report.manual_feedback.length}} 条记录</span></summary><p class="cm-help">只追加当前接受版本的人工意见，不覆盖自动评估；运行停止后可提交。</p><label class="cm-check"><input v-model="manual.passed" type="checkbox"/>人工确认通过</label><div class="cm-form-two"><label>人工改动行数（未知留空）<input v-model.number="manual.lines" type="number" min="0"/></label><label>人工耗时秒（未知留空）<input v-model.number="manual.seconds" type="number" min="0"/></label></div><label>验证范围与备注<textarea v-model="manual.notes" rows="3" maxlength="4000"/></label><button :disabled="!canWrite||['queued','running'].includes(report.status)" @click="emit('feedback')">保存人工记录</button><article v-for="record in report.manual_feedback" :key="record.id" class="cm-feedback-record"><StatusBadge :status="record.passed?'pass':'fail'" :label="record.passed?'人工确认通过':'人工未通过'"/><p>{{record.notes||'未填写备注'}}</p><small>版本 {{record.revision_sha256.slice(0,16)}}</small></article></details>
    <details class="cm-details"><summary>完整报告与原始诊断</summary><pre>{{JSON.stringify(report,null,2)}}</pre></details>
  </section>
</template>
